#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Geospatial : 2

DEF ORIGIN GeoOrigin {
  geoCoords 10 20 0
}

NavigationInfo {
  type [
    "WALK",
    "ANY"
  ]
}

GeoViewpoint {
  geoOrigin USE ORIGIN
  position 10 20 5
  orientation 0 1 0 0.3
}

GeoLocation {
  geoOrigin USE ORIGIN
  geoCoords 10 20 0
  children [
    Shape {
      appearance Appearance {
        material Material {
          diffuseColor 0.5 0.5 0.4
        }
      }
      geometry Box {
        size 200 1 200
      }
    }
    Transform {
      translation 2 1 -12
      children Shape {
        appearance Appearance {
          material Material {
            diffuseColor 0.8 0.2 0.2
          }
        }
        geometry Box {
          size 6 1.2 3
        }
      }
    }
  ]
}

